const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define area of interest - Todoque and El Paraíso, La Palma
  const todoque = ee.Geometry.Point([-17.891, 28.615]);
  const elParaiso = ee.Geometry.Point([-17.888, 28.620]);
  const aoi = ee.Geometry.MultiPoint([todoque, elParaiso]).buffer(2000);

  // 2. Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudMask = qa.bitwiseAnd(1 << 10).eq(0)
                        .and(qa.bitwiseAnd(1 << 11).eq(0));
    return image.updateMask(cloudMask);
  }

  // 3. Function to detect lava using spectral indices
  function detectLava(image) {
    const nir = image.select('B8');
    const swir2 = image.select('B12');
    const nbr = nir.subtract(swir2).divide(nir.add(swir2));
    // Lava has very low NBR values (< -0.3)
    const lava = nbr.lt(-0.25);
    return lava.rename('lava');
  }

  // 4. Get imagery for May 21, 2021
  const date1Start = '2021-05-15';
  const date1End = '2021-05-27';
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(date1Start, date1End)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size1 = await col1.size().getInfo();
  console.log(`May 2021 Images: ${size1}`);

  if (size1 === 0) {
    console.log('No images for May 2021');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Get imagery for December 15, 2021
  const date2Start = '2021-12-10';
  const date2End = '2021-12-20';
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(date2Start, date2End)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size2 = await col2.size().getInfo();
  console.log(`December 2021 Images: ${size2}`);

  if (size2 === 0) {
    console.log('No images for December 2021');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Process May 2021
  const img1 = col1.map(maskClouds).median();
  const lava1 = detectLava(img1);

  const stats1 = await lava1.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const lavaArea1 = stats1.lava_sum || 0;
  const validPixels1 = stats1.lava_count || 0;
  console.log(`May 2021 - Valid pixels: ${validPixels1}, Lava pixels: ${lavaArea1}`);

  if (validPixels1 === 0) {
    console.log('No valid pixels for May 2021');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Process December 2021
  const img2 = col2.map(maskClouds).median();
  const lava2 = detectLava(img2);

  const stats2 = await lava2.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const lavaArea2 = stats2.lava_sum || 0;
  const validPixels2 = stats2.lava_count || 0;
  console.log(`Dec 2021 - Valid pixels: ${validPixels2}, Lava pixels: ${lavaArea2}`);

  if (validPixels2 === 0) {
    console.log('No valid pixels for December 2021');
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Calculate change
  const increase = lavaArea2 - lavaArea1;
  console.log(`Lava pixel increase: ${increase}`);
  console.log(`Lava area increase (hectares): ${(increase * 100 * 100 / 10000).toFixed(2)}`);

  // 9. Final answer
  if (increase > 100) {  // Significant increase (>1 hectare)
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
